#include "anvil/SceneSerializer.h"
#include <algorithm>
#include <cmath>
#include <fstream>
#include <iomanip>
#include <regex>
#include <sstream>

namespace anvil { namespace {
std::string quote(const std::string& s) { std::ostringstream o; o << '"'; for (unsigned char c : s) { switch(c) { case '"': o << "\\\""; break; case '\\': o << "\\\\"; break; case '\n': o << "\\n"; break; case '\r': o << "\\r"; break; case '\t': o << "\\t"; break; default: if(c < 32) o << ' '; else o << c; } } o << '"'; return o.str(); }
std::string unquote(const std::string& s) { std::string r; for(size_t i=1;i+1<s.size();++i) { char c=s[i]; if(c=='\\' && i+1<s.size()-1) { char n=s[++i]; r += n=='n'?'\n':n=='r'?'\r':n=='t'?'\t':n; } else r+=c; } return r; }
std::string field(const std::string& o,const char* key,const std::string& fallback="0") { std::smatch m; std::regex re(std::string("\\\"")+key+"\\\"\\s*:\\s*(\\\"(?:\\\\.|[^\\\"])*\\\"|\\[[^\\]]*\\]|[^,}]+)"); return std::regex_search(o,m,re)?m[1].str():fallback; }
float number(const std::string& o,const char* k,float d=0) { try { return std::stof(field(o,k,std::to_string(d))); } catch(...) { return d; } }
uint32_t integer(const std::string& o,const char* k,uint32_t d=0) { try { return static_cast<uint32_t>(std::stoul(field(o,k,std::to_string(d)))); } catch(...) { return d; } }
bool boolean(const std::string& o,const char* k,bool d=false) { auto v=field(o,k,d?"true":"false"); return v=="true" || v=="1"; }
glm::vec3 vec(const std::string& o,const char* k,glm::vec3 d=glm::vec3(0)) { auto v=field(o,k); std::regex re(R"([-+]?(?:\d*\.)?\d+(?:[eE][-+]?\d+)?)"); std::sregex_iterator i(v.begin(),v.end(),re),e; float a[3]={d.x,d.y,d.z}; for(int n=0;n<3 && i!=e;++n,++i) try{a[n]=std::stof(i->str());}catch(...){} return {a[0],a[1],a[2]}; }
void putVec(std::ostringstream& o,const char* k,glm::vec3 v) { o << quote(k) << ":[" << v.x << ',' << v.y << ',' << v.z << ']'; }
std::size_t matchingBracket(const std::string& s,std::size_t open) { int depth=0; bool quoted=false,escape=false; for(std::size_t i=open;i<s.size();++i){char c=s[i];if(quoted){if(escape)escape=false;else if(c=='\\')escape=true;else if(c=='"')quoted=false;continue;}if(c=='"'){quoted=true;continue;}if(c=='[')++depth;else if(c==']'&&--depth==0)return i;}return std::string::npos; }

// M32 (format v5): Rigidbody fields are written flat with a "phys" prefix because the object regex cannot parse nested braces.
void putPhysics(std::ostringstream& o,const Entity& e){const auto&c=e.physics;o<<",\"phys\":"<<(c.enabled?"true":"false")<<",\"physShape\":"<<int(c.shape)<<",\"physMotion\":"<<int(c.motion)<<",\"physAutoFit\":"<<(c.autoFit?"true":"false")<<',';putVec(o,"physHalf",c.halfExtents);o<<",\"physRadius\":"<<c.radius<<",\"physHalfHeight\":"<<c.halfHeight<<",\"physMass\":"<<c.mass<<",\"physFriction\":"<<c.friction<<",\"physRestitution\":"<<c.restitution<<",\"physLinDamp\":"<<c.linearDamping<<",\"physAngDamp\":"<<c.angularDamping<<",\"physGravity\":"<<c.gravityScale<<",\"physTrigger\":"<<(c.isTrigger?"true":"false")<<",\"physCCD\":"<<(c.continuous?"true":"false");}
float finiteOr(float v,float lo,float hi,float d){return std::isfinite(v)?std::clamp(v,lo,hi):d;}
void readPhysics(const std::string& x,Entity& e){auto&c=e.physics;c.enabled=boolean(x,"phys");c.shape=static_cast<physics::ShapeType>(std::min(integer(x,"physShape"),2u));c.motion=static_cast<physics::MotionType>(std::min(integer(x,"physMotion",2),2u));c.autoFit=boolean(x,"physAutoFit",true);c.halfExtents=glm::max(glm::abs(vec(x,"physHalf",glm::vec3(1))),glm::vec3(0.001f));c.radius=finiteOr(number(x,"physRadius",1),0.001f,1e4f,1);c.halfHeight=finiteOr(number(x,"physHalfHeight",.5f),0.001f,1e4f,.5f);c.mass=finiteOr(number(x,"physMass",1),0.0001f,1e7f,1);c.friction=finiteOr(number(x,"physFriction",.6f),0,1,.6f);c.restitution=finiteOr(number(x,"physRestitution",.05f),0,1,.05f);c.linearDamping=finiteOr(number(x,"physLinDamp",.02f),0,20,.02f);c.angularDamping=finiteOr(number(x,"physAngDamp",.05f),0,20,.05f);c.gravityScale=finiteOr(number(x,"physGravity",1),-10,10,1);c.isTrigger=boolean(x,"physTrigger");c.continuous=boolean(x,"physCCD");}
}
std::string SceneSerializer::toJson(const Scene& s) { std::ostringstream o; o<<std::setprecision(9)<<"{\n\"version\":"<<kVersion<<",\n\"sun\":{"; putVec(o,"direction",s.sun.direction); o<<','; putVec(o,"color",s.sun.color); o<<",\"intensity\":"<<s.sun.intensity<<"},\n\"entities\":[\n";
for(size_t i=0;i<s.entities.size();++i){const auto&e=s.entities[i]; o<<"{\"id\":"<<e.id<<",\"parentId\":"<<e.parentId<<",\"name\":"<<quote(e.name)<<",\"active\":"<<(e.active?"true":"false")<<','; putVec(o,"position",e.position); o<<','; putVec(o,"rotation",e.rotation); o<<','; putVec(o,"scale",e.scale); o<<",\"primitive\":"<<int(e.primitive)<<','; putVec(o,"albedo",e.material.albedo); o<<",\"roughness\":"<<e.material.roughness<<",\"metallic\":"<<e.material.metallic<<",\"albedoTexturePath\":"<<quote(e.material.albedoTexturePath)<<",\"modelPath\":"<<quote(e.modelPath)<<",\"isLight\":"<<(e.isLight?"true":"false")<<','; putVec(o,"lightColor",e.lightColor); o<<",\"lightIntensity\":"<<e.lightIntensity<<",\"orbit\":"<<(e.orbit?"true":"false")<<','; putVec(o,"orbitCenter",e.orbitCenter); o<<",\"orbitRadius\":"<<e.orbitRadius<<",\"orbitSpeed\":"<<e.orbitSpeed<<",\"orbitPhase\":"<<e.orbitPhase; putPhysics(o,e); o<<'}'<<(i+1<s.entities.size()?",":"")<<'\n'; }
o<<"]\n}\n"; return o.str(); }
bool SceneSerializer::fromJson(Scene& scene,const std::string& json,std::string* error) { auto fail=[&](const char*m){if(error)*error=m;return false;}; const auto version = static_cast<unsigned>(number(json,"version",0)); if(version < 1 || version > kVersion) return fail("Unsupported or missing scene format version"); auto ep=json.find("\"entities\""); if(ep==std::string::npos) return fail("Missing entities array"); auto lb=json.find('[',ep), rb=lb==std::string::npos?std::string::npos:matchingBracket(json,lb); if(lb==std::string::npos||rb==std::string::npos) return fail("Malformed entities array"); std::string body=json.substr(lb+1,rb-lb-1); Scene candidate; candidate.sun.direction=vec(json.substr(0,ep),"direction",candidate.sun.direction); candidate.sun.color=vec(json.substr(0,ep),"color",candidate.sun.color); candidate.sun.intensity=number(json.substr(0,ep),"intensity",candidate.sun.intensity); std::regex obj(R"(\{[^{}]*\})"); uint32_t maxId=0; for(std::sregex_iterator it(body.begin(),body.end(),obj),end;it!=end;++it){std::string x=it->str(); Entity e; e.id=integer(x,"id"); e.parentId=version >= 2 ? integer(x,"parentId",0) : 0; if(!e.id)return fail("Entity has invalid id"); if(candidate.find(e.id))return fail("Duplicate entity id"); auto nm=field(x,"name","\"Entity\""); e.name=unquote(nm); e.active=boolean(x,"active",true); e.position=vec(x,"position"); e.rotation=vec(x,"rotation"); e.scale=vec(x,"scale",glm::vec3(1)); e.primitive=static_cast<Primitive>(std::min(integer(x,"primitive"),4u)); e.material.albedo=vec(x,"albedo",glm::vec3(.8f)); e.material.roughness=number(x,"roughness",.5f); e.material.metallic=number(x,"metallic"); if(version>=3)e.material.albedoTexturePath=unquote(field(x,"albedoTexturePath","\"\"")); if(version>=4)e.modelPath=unquote(field(x,"modelPath","\"\"")); e.isLight=boolean(x,"isLight"); e.lightColor=vec(x,"lightColor",glm::vec3(1)); e.lightIntensity=number(x,"lightIntensity",60); e.orbit=boolean(x,"orbit"); e.orbitCenter=vec(x,"orbitCenter",{0,4,3}); e.orbitRadius=number(x,"orbitRadius",8); e.orbitSpeed=number(x,"orbitSpeed",.6f); e.orbitPhase=number(x,"orbitPhase"); if(version>=5)readPhysics(x,e); candidate.entities.push_back(std::move(e)); maxId=std::max(maxId,candidate.entities.back().id); }
// Validate parent references and reject cycles before committing the candidate scene.
for (const Entity& e : candidate.entities) {
    if (e.parentId && !candidate.find(e.parentId)) return fail("Entity references a missing parent");
    uint32_t cursor = e.parentId; size_t guard = 0;
    while (cursor && guard++ <= candidate.entities.size()) {
        if (cursor == e.id) return fail("Hierarchy contains a cycle");
        const Entity* p = nullptr; for (const Entity& n : candidate.entities) if (n.id == cursor) { p = &n; break; }
        if (!p) break; cursor = p->parentId;
    }
}
scene.stopPhysics(); scene.entities=std::move(candidate.entities); scene.sun=candidate.sun; // nextId is advanced through public API below
for(uint32_t id=1;id<=maxId;++id) { if(!scene.find(id)) continue; } scene.setNextId(maxId+1); return true; }
bool SceneSerializer::save(const Scene&s,const std::filesystem::path&p,std::string*e){std::ofstream f(p,std::ios::binary);if(!f){if(e)*e="Cannot open scene file for writing";return false;}auto data=toJson(s);f.write(data.data(),static_cast<std::streamsize>(data.size()));if(!f){if(e)*e="Failed while writing scene file";return false;}return true;}
bool SceneSerializer::load(Scene&s,const std::filesystem::path&p,std::string*e){std::ifstream f(p,std::ios::binary);if(!f){if(e)*e="Cannot open scene file";return false;}std::ostringstream b;b<<f.rdbuf();if(!f.good()&&!f.eof()){if(e)*e="Failed while reading scene file";return false;}return fromJson(s,b.str(),e);}
}
